const t={async request(t,e){const s=`http://localhost:7071/api${t.startsWith("/")?"":"/"}${t}`,r=await fetch(s,{...e,headers:{"Content-Type":"application/json",...e?.headers}});if(!r.ok){const t=await r.json().catch(()=>({}));throw new Error(`API Error: ${r.status} - ${t.message||r.statusText}`)}return r.json()},async get(t){return this.request(t,{method:"GET"})},async post(t,e){return this.request(t,{method:"POST",body:JSON.stringify(e)})},async put(t,e){return this.request(t,{method:"PUT",body:JSON.stringify(e)})},async patch(t,e){return this.request(t,{method:"PATCH",body:JSON.stringify(e)})},async delete(t){return this.request(t,{method:"DELETE"})}};export{t as a};
